+        return null;
+    }
+
+    internal static int? ReadTrainingSingleLevel(JsonElement root)
+    {
+        if (root.TryGetProperty("level", out var level) &&
+            level.ValueKind == JsonValueKind.Number)
+            return level.GetInt32();
+
+        return null;
+    }
+}
